alter table public.voice_pricing add constraint voice_pricing_currency_check CHECK ((currency ~ '^[A-Z]{3}$'::text));
alter table public.voice_pricing add constraint voice_pricing_provider_check CHECK ((provider = ANY (ARRAY['vapi'::text, 'telnyx'::text, 'twilio'::text, 'llm'::text, 'other'::text])));
alter table public.voice_pricing add constraint voice_pricing_unit_cost_check CHECK ((unit_cost >= (0)::numeric));
alter table public.waitlist_entries add constraint waitlist_entries_pkey PRIMARY KEY (id);
alter table public.waitlist_entries add constraint waitlist_entries_status_check CHECK ((status = ANY (ARRAY['waiting'::text, 'offered'::text, 'booked'::text, 'removed'::text])));
alter table public.waitlist_offer_links add constraint waitlist_offer_links_pkey PRIMARY KEY (id);
alter table public.waitlist_offer_links add constraint waitlist_offer_links_token_hash_key UNIQUE (token_hash);
alter table public.website_forms add constraint website_forms_pkey PRIMARY KEY (id);
alter table public.website_forms add constraint website_forms_public_key_key UNIQUE (public_key);
alter table public.website_pages add constraint website_pages_pkey PRIMARY KEY (id);
alter table public.website_pages add constraint website_pages_source_id_url_key UNIQUE (source_id, url);
alter table public.website_pages add constraint website_pages_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'ignored'::text, 'missing'::text, 'broken'::text])));
alter table public.website_sources add constraint website_sources_pkey PRIMARY KEY (id);
alter table public.website_sources add constraint website_sources_business_id_host_key UNIQUE (business_id, host);
alter table public.website_sources add constraint website_sources_frequency_hours_check CHECK (((frequency_hours >= 6) AND (frequency_hours <= 720)));
alter table public.website_sources add constraint website_sources_max_pages_check CHECK (((max_pages >= 1) AND (max_pages <= 100)));
alter table public.website_sources add constraint website_sources_status_check CHECK ((status = ANY (ARRAY['pending_approval'::text, 'active'::text, 'paused'::text])));
alter table public.workflow_executions add constraint workflow_executions_pkey PRIMARY KEY (id);
alter table public.workflow_executions add constraint workflow_executions_status_check CHECK ((status = ANY (ARRAY['running'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text])));
alter table public.zella_milestones add constraint zella_milestones_pkey PRIMARY KEY (business_id, key);
